CREATE TABLE app_user (id UUID PRIMARY KEY, email VARCHAR(320) NOT NULL UNIQUE, password_hash VARCHAR(100) NOT NULL, display_name VARCHAR(100) NOT NULL, created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE workspace (id UUID PRIMARY KEY, name VARCHAR(120) NOT NULL, owner_id UUID NOT NULL REFERENCES app_user(id), created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE workspace_member (workspace_id UUID NOT NULL REFERENCES workspace(id) ON DELETE CASCADE,user_id UUID NOT NULL REFERENCES app_user(id) ON DELETE CASCADE,role VARCHAR(16) NOT NULL,joined_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(workspace_id,user_id));
CREATE TABLE project (id UUID PRIMARY KEY,workspace_id UUID NOT NULL REFERENCES workspace(id) ON DELETE CASCADE,name VARCHAR(160) NOT NULL,description VARCHAR(2000) DEFAULT '',status VARCHAR(24) DEFAULT 'PLANNING',due_date DATE,created_by UUID NOT NULL REFERENCES app_user(id),created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX project_workspace_updated_idx ON project(workspace_id,updated_at);
CREATE TABLE project_member (project_id UUID NOT NULL REFERENCES project(id) ON DELETE CASCADE,user_id UUID NOT NULL REFERENCES app_user(id) ON DELETE CASCADE,PRIMARY KEY(project_id,user_id));
CREATE TABLE task (id UUID PRIMARY KEY,project_id UUID NOT NULL REFERENCES project(id) ON DELETE CASCADE,title VARCHAR(240) NOT NULL,description VARCHAR(4000) DEFAULT '',status VARCHAR(24) DEFAULT 'BACKLOG',priority VARCHAR(12) DEFAULT 'NORMAL',assignee_id UUID REFERENCES app_user(id) ON DELETE SET NULL,due_date DATE,position INTEGER DEFAULT 0,created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX task_project_status_position_idx ON task(project_id,status,position);
CREATE TABLE document (id UUID PRIMARY KEY,workspace_id UUID NOT NULL REFERENCES workspace(id) ON DELETE CASCADE,project_id UUID REFERENCES project(id) ON DELETE SET NULL,title VARCHAR(240) NOT NULL,kind VARCHAR(16) DEFAULT 'RICH_TEXT',content TEXT NOT NULL,owner_id UUID NOT NULL REFERENCES app_user(id),created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE notification (id UUID PRIMARY KEY,user_id UUID NOT NULL REFERENCES app_user(id) ON DELETE CASCADE,kind VARCHAR(32) NOT NULL,title VARCHAR(240) NOT NULL,body VARCHAR(4000) DEFAULT '',read_at TIMESTAMP WITH TIME ZONE,created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP);
